SELECT id, subject, kind, state, send_id, connection_id, session_id, CAST(sent_version AS TEXT) AS sent_version, typeof(sent_version) AS sent_version_class, CAST(next_attempt_at AS TEXT) AS next_attempt_at, typeof(next_attempt_at) AS next_attempt_class, CAST(attempts AS TEXT) AS attempts, typeof(attempts) AS attempts_class, CAST(first_failed_at AS TEXT) AS first_failed_at, typeof(first_failed_at) AS first_failed_class, last_error_class, last_error, CAST(created_at AS TEXT) AS created_at, typeof(created_at) AS created_class, CAST(updated_at AS TEXT) AS updated_at, typeof(updated_at) AS updated_class FROM central_work_attempts WHERE subject=?1 AND kind=?2;
